import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// The model library keeps fixed filenames (prefabs.glb/json) but its contents are
// regenerated by the Blender pipeline and the CC0 merge. Stamping the build time into
// the bundle throws away any cached copy, so a reload always sees the library that is
// on disk instead of silently skipping every newly added id as "missing".
const BUILD_STAMP = Date.now().toString(36);

export default defineConfig({
  plugins: [react()],
  define: {
    __BUILD_STAMP__: JSON.stringify(BUILD_STAMP),
  },
  server: {
    port: 5173,
    strictPort: true,
    // the game's own local server: AI provider settings, region jobs and the GLB
    // files Blender builds at runtime (see server/index.mjs)
    proxy: {
      '/api': { target: 'http://127.0.0.1:8787', changeOrigin: false },
      '/generated': { target: 'http://127.0.0.1:8787', changeOrigin: false },
    },
  },
  build: {
    target: 'es2022',
  },
});
